{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In a first-in-human study, PTC518 achieved CSF concentrations approximately 2.6-fold higher than unbound plasma concentrations, providing direct human evidence of meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "T-3811ME entered CSF readily in rabbits, with CSF/serum AUC penetration of 13–16%, directly demonstrating meaningful blood-brain barrier access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Decursin showed brain-to-plasma ratios greater than 1.5 over 0.5–5 h after oral dosing in rats, indicating good brain penetration in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "[18F]AZAN exhibited remarkably high brain uptake in baboon and human PET studies, confirming robust BBB crossing in higher species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "[18F]d8 showed excellent brain uptake and metabolic stability in mouse dynamic PET imaging, supporting favorable CNS access for this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental records, including direct human CSF, rabbit CSF, rat brain/plasma, and PET brain-uptake measurements, consistently indicate meaningful CNS access for close analogues. The physicochemical prior is also favorable for passive BBB penetration, so the query is predicted to pass.",
  "evidence_gaps": [
    "No direct CNS pharmacokinetic measurement for the exact query molecule",
    "Efflux transporter phenotype is not directly measured; moderate P-gp risk remains",
    "Several supportive records are radiolabeled PET tracers, though their transfer scores are high"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

